CREATE TABLE product_reviews(id BIGINT NOT NULL AUTO_INCREMENT,order_item_id BIGINT NOT NULL,product_id BIGINT NOT NULL,customer_id BIGINT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(1000) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_review_order_item UNIQUE(order_item_id),CONSTRAINT fk_review_item FOREIGN KEY(order_item_id) REFERENCES order_items(id),CONSTRAINT fk_review_product FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT fk_review_customer FOREIGN KEY(customer_id) REFERENCES app_users(id),CONSTRAINT chk_review_rating CHECK(rating BETWEEN 1 AND 5));
